interface Item {
  priority: number;
  order: number;
  value: string;
}

export class StablePriorityQueue {
  private items: Item[] = [];
  private counter = 0;

  push(priority: number, value: string): void {
    this.items.push({ priority, order: this.counter++, value });
    this.items.sort((a, b) => a.priority - b.priority || a.order - b.order);
  }

  pop(): string | undefined {
    return this.items.shift()?.value;
  }
}

files.pq.ts:
interface Item {
  priority: number;
  order: number;
  value: string;
}

export class StablePriorityQueue {
  private items: Item[] = [];
  private counter = 0;

  push(priority: number, value: string): void {
    this.items.push({ priority, order: this.counter, value });
    this.counter -= 1;
    this.items.sort((a, b) => a.priority - b.priority || a.order - b.order);
  }

  pop(): string | undefined {
    return this.items.shift()?.value;
  }
}

