const assert = require("assert");
const { StablePriorityQueue } = require("./build/pq.js");

{
  const q = new StablePriorityQueue();
  q.push(5, "low");
  q.push(1, "high");
  q.push(3, "mid");
  assert.deepStrictEqual([q.pop(), q.pop(), q.pop()], ["high", "mid", "low"]);
}
{
  const q = new StablePriorityQueue();
  q.push(1, "first");
  q.push(2, "other");
  q.push(1, "second");
  assert.strictEqual(q.pop(), "first");
  q.push(1, "third");
  assert.deepStrictEqual([q.pop(), q.pop()], ["second", "third"]);
}
console.log("behavior OK");
